export interface Env {
	GITHUB_TOKEN: string;
	AUTH_TOKEN: string;
}

const RUN_URL_PATTERN = /^https:\/\/github\.com\/entireio\/cli\/actions\/runs\/\d+$/;
const REPO = "entireio/cli";

function escapeHtml(str: string): string {
	return str.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

function htmlPage(title: string, body: string): Response {
	return new Response(
		`<!DOCTYPE html>\n<html><body>\n<h2>${title}</h2>\n${body}\n</body></html>`,
		{ headers: { "Content-Type": "text/html; charset=utf-8" } },
	);
}

async function dispatchWorkflow(
	env: Env,
	workflow: string,
	inputs: Record<string, string>,
): Promise<Response> {
	const resp = await fetch(
		`https://api.github.com/repos/${REPO}/actions/workflows/${workflow}/dispatches`,
		{
			method: "POST",
			headers: {
				Authorization: `Bearer ${env.GITHUB_TOKEN}`,
				Accept: "application/vnd.github+v3+json",
				"User-Agent": "e2e-triage-trigger-worker",
			},
			body: JSON.stringify({ ref: "main", inputs }),
		},
	);

	if (!resp.ok) {
		const body = await resp.text();
		return new Response(`GitHub API error: ${resp.status} ${body}`, { status: 502 });
	}

	return resp;
}

function handleTriage(request: Request, url: URL, env: Env): Promise<Response> | Response {
	const runURL = url.searchParams.get("run_url");
	const slackChannel = url.searchParams.get("slack_channel") ?? "";
	const slackThreadTS = url.searchParams.get("slack_thread_ts") ?? "";

	if (!runURL || !RUN_URL_PATTERN.test(runURL)) {
		return new Response("Invalid or missing run_url parameter", { status: 400 });
	}

	const safeRunURL = escapeHtml(runURL);

	if (request.method === "GET") {
		return htmlPage(
			"Trigger E2E Triage",
			`<p>This will dispatch the E2E triage workflow for:</p>
<p><a href="${safeRunURL}">${safeRunURL}</a></p>
<form method="POST">
<button type="submit">Run Triage</button>
</form>`,
		);
	}

	if (request.method !== "POST") {
		return new Response("Method not allowed", { status: 405 });
	}

	return (async () => {
		const resp = await dispatchWorkflow(env, "e2e-triage.yml", {
			run_url: runURL,
			slack_channel: slackChannel,
			slack_thread_ts: slackThreadTS,
		});

		if (resp.status === 502) return resp;

		return htmlPage(
			"Triage started",
			`<p>The E2E triage workflow has been dispatched. Check Slack for results.</p>
<p><a href="${safeRunURL}">View original run</a></p>`,
		);
	})();
}

function handleFix(request: Request, url: URL, env: Env): Promise<Response> | Response {
	const triageRunId = url.searchParams.get("triage_run_id");
	const runURL = url.searchParams.get("run_url");
	const failedAgents = url.searchParams.get("failed_agents");
	const slackChannel = url.searchParams.get("slack_channel") ?? "";
	const slackThreadTS = url.searchParams.get("slack_thread_ts") ?? "";

	if (!triageRunId || !/^\d+$/.test(triageRunId)) {
		return new Response("Invalid or missing triage_run_id parameter", { status: 400 });
	}
	if (!runURL || !RUN_URL_PATTERN.test(runURL)) {
		return new Response("Invalid or missing run_url parameter", { status: 400 });
	}
	if (!failedAgents || failedAgents.trim().length === 0) {
		return new Response("Invalid or missing failed_agents parameter", { status: 400 });
	}

	const safeRunURL = escapeHtml(runURL);
	const safeAgents = escapeHtml(failedAgents);

	if (request.method === "GET") {
		return htmlPage(
			"Apply E2E Fix",
			`<p>This will dispatch the E2E fix workflow to apply the plan and create a draft PR.</p>
<p>Failed agents: <strong>${safeAgents}</strong></p>
<p>Original run: <a href="${safeRunURL}">${safeRunURL}</a></p>
<form method="POST">
<button type="submit">Fix It</button>
</form>`,
		);
	}

	if (request.method !== "POST") {
		return new Response("Method not allowed", { status: 405 });
	}

	return (async () => {
		const resp = await dispatchWorkflow(env, "e2e-fix.yml", {
			triage_run_id: triageRunId,
			run_url: runURL,
			failed_agents: failedAgents,
			slack_channel: slackChannel,
			slack_thread_ts: slackThreadTS,
		});

		if (resp.status === 502) return resp;

		return htmlPage(
			"Fix started",
			`<p>The E2E fix workflow has been dispatched. Check Slack for the draft PR link.</p>
<p><a href="${safeRunURL}">View original run</a></p>`,
		);
	})();
}

export default {
	async fetch(request: Request, env: Env): Promise<Response> {
		const url = new URL(request.url);

		const token = url.searchParams.get("token");
		if (!token || token !== env.AUTH_TOKEN) {
			return new Response("Unauthorized", { status: 401 });
		}

		switch (url.pathname) {
			case "/triage":
				return handleTriage(request, url, env);
			case "/fix":
				return handleFix(request, url, env);
			default:
				return new Response("Not found", { status: 404 });
		}
	},
} satisfies ExportedHandler<Env>;
